insert into woerter (slug, wort, artikel, ipa, wortart, kategorie, definition, bedeutungen, beispiel) values
  ('unsare-poimbuschn-erinnan-aun-de-echtn-poimzweigaln-mit-denan-de-leit-in-jesus-beim-einzug-jerusalem-zuagwunkn-haum', 'Unsare Poimbuschn erinnan aun de echtn Poimzweigaln, mit denan de Leit in Jesus beim Einzug Jerusalem zuagwunkn haum!', '', '', '', 'Religiöses & Göttliches auf Wienerisch', 'Unsere Palmbuschen erinnern an die echten Palmenzweige, mit denen die Leute Jesus beim Einzug in Jerusalem zugewunken haben!', '[{"kategorie": "wörtlich", "text": "\"Unsere Palmbuschen stehen stellvertretend für jene Palmzweige, mit denen Jesus beim Einzug in Jerusalem zugejubelt wurde!\"  2. Unsere Palmbuschen symbolisieren die Palmzweige, die man Jesus in Jerusalem entgegenschwenkte!  3. Unsere Palmbuschen vergegenwärtigen die Palmzweige, mit denen die Leute Jesus beim biblischen Einzug in Jerusalem zugewunken haben!"}]'::jsonb, ''),
  ('da-poimeesl-zeigd-uns-da-messias-kummd-ned-hoch-zu-ross-eigriidn-sondan-auf-an-schlichtn-eesl-oiso-in-bescheidnheit-und-friidn', 'Da Poimeesl zeigd uns: Da Messias kummd ned hoch zu Ross eigriidn, sondan auf an schlichtn Eesl - oiso in Bescheidnheit und Friidn!', '', '', '', 'Religiöses & Göttliches auf Wienerisch', 'Der Palmesel zeigt uns: Der Messias kommt nicht hoch zu Ross eingeritten, sondern auf einem schlichten Esel - also in Bescheidenheit und Frieden!', '[{"kategorie": "wörtlich", "text": "\"Der Palmesel macht deutlich: Christus zieht nicht als Krieger auf einem Pferd ein, sondern demütig und friedvoll auf einem Esel!\"  2. Der Palmesel erinnert daran, dass der Messias nicht prunkvoll auf einem Ross erschien, sondern schlicht und friedlich auf einem Esel!  3. Im Palmesel wird sichtbar: Jesus wählte nicht das Streitross, sondern den Esel – ein Symbol von Demut und Frieden!"}]'::jsonb, ''),
  ('fiad-poimsuundogsprozession-wiad-da-poimeesl-aufputzd-wiara-lebendiga-glicksbringa-mit-hooslrutn-poimkatzaln-haeulignbueueda-und-flattarnde-bandln-in-olle-foam', 'Fiad Poimsuundogsprozession wiad da Poimeesl aufputzd wiara lebendiga Glicksbringa - mit Hooslrutn, Poimkatzaln, Häulignbüüda und flattarnde Bandln in olle Foam!', '', '', '', 'Religiöses & Göttliches auf Wienerisch', 'Für die Palmsonntagsprozession wird der Palmesel aufgeputzt wie ein lebendiger Glücksbringer - mit Haselruten, Palmkätzchen, Heiligenbildern und flatternden Bändchen in allen Farben!', '[{"kategorie": "wörtlich", "text": "\"Der Palmesel wird für die Palmsonntagsprozession herausgeputzt wie ein lebendiger Segensbringer – geschmückt mit Haselruten, Palmkätzchen, Heiligenbildern und flatternden Bändchen in allen Farben!\"  2. Der Palmesel wird für die Palmsonntagsprozession in seiner ganzen Pracht enthüllt, einem lebendigen Talisman gleich – geschmückt mit Haselruten, Palmkätzchen, Heiligenbildern und flatternden Bändchen in allen Farben!  3. Der Palmesel wird für die Palmsonntagsprozession geschmückt wie ein heiliges Sinnbild – mit Haselruten, Palmkätzchen, Heiligenbildern und flatternden Bändchen in allen Farben!"}]'::jsonb, ''),
  ('in-poimeesl-schbueuen', 'in Poimeesl schbüün', '', '', '', 'Wiener Sprüche, die sitzen!', 'den Palmesel spielen', '[{"kategorie": "scherzhaft für", "text": "\"der Letzte sein\""}, {"kategorie": "", "text": "\"zu spät kommen\""}, {"kategorie": "", "text": "\"als Nachzügler eintrudeln\""}, {"kategorie": "", "text": "\"das Schlusslicht sein\" (in Anspielung darauf, dass der Palmesel am Palmsonntag stets als Letzter in die Kirche gezogen wurde)"}]'::jsonb, 'I wüü ned schoo wiida in Poimeesl schbüün - oisa zaa au, Schatzi!'),
  ('i-wueue-ned-schoo-wiida-in-poimeesl-schbueuen-oisa-zaa-au-schatzi', 'I wüü ned schoo wiida in Poimeesl schbüün - oisa zaa au, Schatzi!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Ich will nicht schon wieder den Palmesel spielen - also beeil dich, Schatzi!', '[{"kategorie": "wörtlich", "text": "\"Ich will nicht schon wieder der Letzte sein – also mach hin, Schätzchen!\"  2. Ich will nicht schon wieder den Bummelanten geben – also gib Gas, Schatzi!  3. Ich hab keine Lust, wieder als Schlusslicht einzutrudeln – also mach ein bisschen schneller, Liebling!"}]'::jsonb, 'in Poimeesl schbüün'),
  ('aufputzd-wiara-poimeesl', 'aufputzd wiara Poimeesl', '', '', '', 'Wiener Sprüche, die sitzen!', 'aufgeputzt wie ein Palmesel', '[{"kategorie": "scherzhaft für", "text": "\"aufgebrezelt wie zum Opernball\""}, {"kategorie": "", "text": "\"herausgeputzt wie ein Paradiesvogel\""}, {"kategorie": "", "text": "\"aufgebrezelt wie ein Christbaum\""}, {"kategorie": "", "text": "[[aufgeputzt wie ein Pfingstochse]]  (übertrieben bunt und schrill gekleidet)"}]'::jsonb, 'Dea is aufputzd wiara Poimeesl - najo, ea warad soo gean Keenig, owa aum End bleibda des, wosa imma schoo woa: a deppada Eesl!'),
  ('dea-is-aufputzd-wiara-poimeesl-najo-ea-warad-soo-gean-keenig-owa-aum-end-bleibda-des-wosa-imma-schoo-woa-a-deppada-eesl', 'Dea is aufputzd wiara Poimeesl - najo, ea warad soo gean Keenig, owa aum End bleibda des, wosa imma schoo woa: a deppada Eesl!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Der ist aufgeputzt wie ein Palmesel - naja, er wär so gern König, aber am Ende bleibt er das, was er immer schon war: ein depperter Esel!', '[{"kategorie": "wörtlich", "text": "\"Der ist aufgebrezelt wie der Palmesel am Sonntag – naja, er wär so gern König, aber im Kern ist er einfach nur ein blöder Esel!\"  2. Der ist aufgeputzt wie ein Palmesel – aber drunter steckt halt bloß ein Trottel auf zwei Beinen!  3. Der ist herausgeputzt wie ein Palmesel – will gern Paradiesvogel sein, aber bleibt halt doch nur ein depperter Esel!"}]'::jsonb, 'aufputzd wiara Poimeesl'),
  ('de-pania-leesd-si-schee-vom-fleisch-so-muass-sei', 'De Pania leesd si schee vom Fleisch - so muass sei!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Die Panier löst sich schön vom Fleisch – so muss es sein!', '[{"kategorie": "wörtlich", "text": "\"Die Panade löst sich locker vom Fleisch – so muss es sein!\"  2. Die Bröselhaube steht locker weg – genau so passt’s!  3. Die Panier schwebt wie ein goldener Mantel über dem Fleisch – besser geht''s nicht!"}]'::jsonb, ''),
  ('a-goidbraune-panaad-is-des-qualitaetsmeakmoi-von-an-guadn-schnitzl', 'A goidbraune Panaad is des Qualitätsmeakmoi von an guadn Schnitzl!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Eine goldbraune Panade ist das Qualitätsmerkmal von einem guten Schnitzel!', '[{"kategorie": "wörtlich", "text": "\"Eine goldbraune Panade gilt als Qualitätsmerkmal für ein gutes Schnitzel!\"  2. Eine knusprig-goldene Panade ist das Kennzeichen eines perfekt gebackenen Schnitzels!  3. Wenn die Panade goldgelb und locker ist, weiß man: Das Schnitzel ist gelungen!"}]'::jsonb, ''),
  ('in-da-panaad-schdeckd-de-magii-vom-daumpf-dea-bloosd-de-hueuen-auf-und-schoffd-raum-fia-luftige-fuellungan', 'In da Panaad schdeckd de Magii vom Daumpf - dea bloosd de Hüün auf und schoffd Raum fia luftige Füllungan!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'In der Panade steckt die Magie des Dampfes – der bläst die Hülle auf und schafft Raum für luftige Füllungen!', '[{"kategorie": "wörtlich", "text": "\"Im Brühteig steckt die Magie des Dampfes – er pustet die Hülle auf und schafft Raum für luftige Füllungen!\"  2. Der Brühteig nutzt die Kraft des Wasserdampfes – dadurch bläht er sich auf und bildet Hohlräume für Füllungen!  3. Beim Brandteig wirkt der Dampf als Triebmittel: Er hebt die Hülle an und schafft Platz für Cremes und Füllungen!"}]'::jsonb, ''),
  ('de-kneedl-wean-mit-aana-eikochdn-panaad-gschdreckd', 'De Kneedl wean mit aana eikochdn Panaad gschdreckd!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Die Knödel werden mit einer eingekochten Panade gestreckt!', '[{"kategorie": "wörtlich", "text": "\"Die Klöße werden mit einer eingekochten Brotpanade gestreckt!\"  2. Um mehr Masse zu bekommen, streckt man die Knödel mit einer vorgekochten Brotteigmasse!  3. Für die Knödelmasse verwendet man eine eingekochte Weißbrotpanade als Streckmittel!"}]'::jsonb, ''),
  ('hau-di-ind-pania', 'Hau di ind Pania!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Hau'' dich in die Panier', '[{"kategorie": "wörtlich", "text": "\"Schmeiß dich ins Gewand!\"  2. \"Spring in die Klamotten!\"  3. \"Wirf dich in die Montur!\""}]'::jsonb, ''),
  ('si-ind-pania-haun', 'si ind Pania haun', '', '', '', 'Wiener Sprüche, die sitzen!', 'sich in die Panier hauen', '[{"kategorie": "wörtlich", "text": "\"sich ins Gewand schmeißen\""}, {"kategorie": "", "text": "\"in seine Klamotten springen\""}, {"kategorie": "", "text": "\"sich in die Montur werfen\""}]'::jsonb, 'Gee, hau di schnöö ind Pania - de Gäst kumman jeedn Moment!'),
  ('gee-hau-di-schnoeoe-ind-pania-de-gaest-kumman-jeedn-moment', 'Gee, hau di schnöö ind Pania - de Gäst kumman jeedn Moment!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Geh, hau dich schnell in die Panier - die Gäste kommen jeden Moment!', '[{"kategorie": "wörtlich", "text": "\"Los, schmeiß dich schnell ins Gewand - die Gäste kommen jeden Moment!\"  2. Hopp, spring in deine Klamotten – die Gäste sind gleich da!  3. Schnell, ab in die Montur – sonst erwischen dich die Gäste im Pyjama!"}]'::jsonb, 'si ind Pania haun'),
  ('moch-a-saeun-i-blaadl-dawaeu-umd-pania', 'Moch a Säun, I blaadl dawäu umd Pania!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Mach ''ne Säule, ich blattle derweil um die Panier!', '[{"kategorie": "scherzhaft für", "text": "\"Bleib hier stehen, ich gehe inzwischen die Garderobe holen!\"  2. Warte hier, ich wühle mich inzwischen durch die Menge bis zu unserem Gewand!  3. Beweg dich nicht von der Stelle - ich bahne mir inzwischen den Weg durch die Menge bis zu unseren Klamotten!"}]'::jsonb, ''),
  ('a-pantschal-is-wiara-schnoeoes-dessea-kuaz-siass-und-glei-wiida-vuabei', 'A Pantschal is wiara schnöös Dessea - kuaz, siass und glei wiida vuabei!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Ein Pantscherl ist wie ein schnelles Dessert: kurz, süß und gleich wieder vorbei!', '[{"kategorie": "wörtlich", "text": "\"Ein Pantscherl ist wie ein Stück Schokolade: rasch vernascht und schnell vergessen!\"  2. Ein Pantscherl ist wie eine Kerze im Wind: flackert kurz und geht schnell aus!  3. Ein Pantscherl ist wie ein Glückskeks: nette Überraschung, aber nach dem Knacken schon gegessen!"}]'::jsonb, ''),
  ('de-zwaa-haum-a-pantschal-ghobt', 'De zwaa haum a Pantschal ghobt!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Die zwei haben ein Pantscherl gehabt!', '[{"kategorie": "wörtlich", "text": "\"Die beiden hatten eine flüchtige Affäre!\"  2. Die beiden hatten ein kurzzeitiges Verhältnis miteinander!  3. Die beiden hatten ein [[Gspusi]] miteinander!"}]'::jsonb, ''),
  ('des-weib-hod-a-pappulatua-de-muassd-waunns-tood-is-no-amoi-extra-daschloong', 'Des Weib hod a Pappulatua! De muassd, waunns tood is, no amoi extra daschloong!"', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Dieses Weib hat eine Pappulatur! Die musst du, wenn sie tot ist, nochmals extra erschlagen!', '[{"kategorie": "wörtlich", "text": "\"Dieses Weib hat ein derartiges Mundwerk, dass du sie als Tote nochmals extra erschlagen musst!\"  2. Das Mundwerk von diesem Weib läuft wie ein Motor, den nicht mal der Tod stoppen kann!  3. Diese Frau hat eine Zunge wie ein Maschinengewehr, das auch posthum noch feuert!"}]'::jsonb, ''),
  ('si-riad-dem-klaan-an-popp-aus-moeoe-und-wossa-au-gaunz-wiad-oma-friara-im-kriag', 'Si riad dem Klaan an Popp aus Möö und Wossa au - gaunz wiad Oma friara im Kriag!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Sie rührt dem Kleinen einen Papp aus Mehl und Wasser an - wie die Oma früher im Krieg!', '[{"kategorie": "wörtlich", "text": "\"Sie kocht dem Kleinen einen Brei aus Mehl und Wasser – genau wie Oma es im Krieg gemacht hat!\"  2. Sie macht dem Kind einen einfachen Mehlbrei, wie ihn schon die Großmutter im Krieg zubereitet hat!  3. Sie rührt dem Kind einen schlichten Brei aus Mehl und Wasser an – ein stilles Erbe aus Omas Kriegsjahren!"}]'::jsonb, ''),
  ('da-popp-dens-eam-im-schbitoi-seaviad-haum-woar-unta-olla-sau', 'Da Popp, dens eam im Schbitoi seaviad haum, woar unta olla Sau!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Der Papp, den sie ihm im Spital serviert haben, war unter aller Sau!', '[{"kategorie": "wörtlich", "text": "\"Der Fraß, den sie ihm im Krankenhaus aufgetischt haben, war eine echte Zumutung!\"  2. Was man ihm im Spital vorsetzte, erinnerte eher an Tapetenkleister als an eine Mahlzeit!  3. Das vermeintliche Essen im Krankenhaus war ein ungenießbarer, klebriger Brei - unter aller Kanone!"}]'::jsonb, ''),
  ('im-kriag-woa-moeoepopp-oft-des-aanzige-wos-kinda-zum-essn-kriagd-haum', 'Im Kriag woa Mööpopp oft des aanzige, wos Kinda zum Essn kriagd haum!', '', '', '', 'Wiener Wörter mit schillernder Geschichte', 'Im Krieg war Mehlpapp oft das einzige, was Kinder zu essen gekriegt haben!', '[{"kategorie": "wörtlich", "text": "\"Während des Krieges war Mehlbrei für viele Kinder oft die einzige Mahlzeit!\"  2. In den düsteren Tagen des Krieges bekamen die Kinder oft nur dünnen Mehlbrei zu essen!  3. Für viele Kinder war ein Löffel lauwarmer Mehlpapp im Krieg schon ein Festmahl!"}]'::jsonb, ''),
  ('egal-wos-ia-oida-kochd-aum-schluss-kummd-imma-nua-a-moeoepopp-ausse', 'Egal, wos ia Oida kochd - aum Schluss kummd imma nua a Mööpopp ausse!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Egal, was ihr alter kocht - am Schluss kommt nur ein Mehlpapp raus!', '[{"kategorie": "wörtlich", "text": "\"Ganz egal, was ihr Kerl kocht – am Ende landet immer der gleiche Papp auf dem Teller!\"  2. Ihr Mann kann kochen, was er will – am Schluss kommt wieder dieser fade Mehlbrei raus!  3. Ob Suppe oder Auflauf – bei ihrem Alten schmeckt alles wie matschige Pampe!"}]'::jsonb, ''),
  ('dem-is-da-popp-schdeigad-wuan', 'Dem is da Popp schdeigad wuan!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Dem ist der Papp steigert geworden!', '[{"kategorie": "wörtlich", "text": "\"Dem ist der Kleister ins Hirn gestiegen!\"  2. Der ist nicht mehr ganz bei Trost!  3. Dem ist der Verstand abhanden gekommen!"}]'::jsonb, ''),
  ('dem-is-da-moeoepopp-ins-hian-gschdiing', 'Dem is da Mööpopp ins Hian gschdiing!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Dem ist der Mehlpapp ins Hirn gestiegen!', '[{"kategorie": "wörtlich", "text": "\"Dem ist der Kleister ins Hirn gestiegen!\"  2. Der ist nicht mehr ganz bei Trost!  3. Dem ist der Verstand abhanden gekommen!"}]'::jsonb, ''),
  ('dea-hod-popp-im-hian', 'Dea hod Popp im Hian!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Der hat Papp im Hirn!', '[{"kategorie": "wörtlich", "text": "\"Der hat nur Brei im Hirn!\"  2. Der ist nicht ganz bei Trost!  3. Dem ist der Verstand abhanden gekommen!"}]'::jsonb, ''),
  ('moch-kan-popp', 'Moch kan Popp!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Mach keinen Papp!', '[{"kategorie": "wörtlich", "text": "\"Mach keinen Scheiß!\"  2. \"Stell dich nicht so an!\"  3. \"Mach nicht so ein Theater!\"  4. \"Lass den Unsinn!\"  5. \"Mach keine Faxen!\""}]'::jsonb, ''),
  ('moch-kann-popp-und-iss-jetzt-endlich-auf', 'Moch kann Popp und iss jetzt endlich auf!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Mach keinen Papp und iss jetzt endlich auf!', '[{"kategorie": "wörtlich", "text": "\"Mach kein Theater und iss jetzt endlich auf!\"  2. Stell dich nicht so an und iss endlich auf!  3. Jetzt zier dich nicht so und schling''s endlich runter!"}]'::jsonb, 'Moch kan Popp!'),
  ('oida-i-kaunn-ned-amoi-mea-popp-soong', 'Oida, I kaunn ned amoi mea "Popp" soong!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Alter, ich kann nicht einmal mehr ''Papp'' sagen!', '[{"kategorie": "wörtlich", "text": "\"Alter, ich bin pappsatt!\"  2. Junge, ich bin bis oben hin vollgefressen!\"  3. Mann, ich bin so satt, ich kann mich nicht mal mehr über den Tisch lehnen!  4. Ehrlich, ich bin so satt sein wie ein [[Firmling]]"}]'::jsonb, ''),
  ('des-griasskoch-poppd-ma-in-da-goschn-wiara-leffae-leim', 'Des Griasskoch poppd ma in da Goschn wiara Leffä Leim!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Das Grießkoch pappt mir in der Goschen wie ein Löffel Leim!', '[{"kategorie": "wörtlich", "text": "\"Der Grießbrei klebt mir im Mund wie ein Löffel Tapetenkleister!\"  2. Das Grießkoch ist so pappig, ich brauch ''ne Spachtel zum Runterschlucken!  3. Der Grießbrei pickt mir am Gaumen wie Sekundenkleber!"}]'::jsonb, ''),
  ('popp-eam-ane', 'Popp eam ane!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Papp'' ihm eine!', '[{"kategorie": "wörtlich", "text": "\"Kleb'' ihm eine!\"  2. \"Gib ihm eine Watschen!\"  3. \"Pick ihm eine!\"  4. \"Verpass ihm eine Ohrfeige!\""}]'::jsonb, ''),
  ('pick-eam-ane', 'Pick eam ane!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Pick'' ihm eine!', '[{"kategorie": "wörtlich", "text": "\"Kleb'' ihm eine!\"  2. \"Gib ihm eine Watschen!\"  3. \"Papp'' ihm eine!\"  4. \"Verpass ihm eine Ohrfeige!\""}]'::jsonb, ''),
  ('waun-da-schnaeae-poppad-wiad-schnoi-i-de-schii-oo-und-bau-min-buam-an-schnaeaemau', 'Waun da Schnää poppad wiad, schnoi I de Schii oo und bau min Buam an Schnäämau!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Wenn der Schnee pappig wird, schnall ich die Skier ab und baue mit dem Buben einen Schneemann!', '[{"kategorie": "wörtlich", "text": "\"Wenn der Schnee patzig wird, schnall ich die Skier ab und baue mit meinem Sohn einen Schneemann!\"  2. Wenn der Schnee klebrig wird, lassen wir die Skier stehen und rollen Schneemannkugeln!  3. Wenn der Schnee so pickt, dass man bei jedem Schwung kleben bleibt, wird’s Zeit zum Schneemannbauen!"}]'::jsonb, ''),
  ('fia-den-poppadn-frooss-brauchsd-kaan-koch-sondan-an-leimriara', 'Fia den poppadn Frooss brauchsd kaan Koch, sondan an Leimriara!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Für diesen pappigen Fraß braucht man keinen Koch, sondern einen Leimrührer!', '[{"kategorie": "wörtlich", "text": "\"Das ist kein Essen, das ist Tapetenkleister! – Ist der Koch vieleicht gelernter Tapezierer?\"  2. Dieser pappige Fraß würde glatt an der Wand kleben bleiben - da brauchst keinen Tapetenkleister mehr!  3. Wie kann man nur einen derart klebrigen Brei anrühren - ist der Koch im Hauptberuf vielleicht Tapezierer?"}]'::jsonb, ''),
  ('a-guads-bappal-waeamd-de-soeoe-und-fueued-de-waumpn', 'A guads Bappal wäamd de Söö und füüd de Waumpn!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Ein gutes Papperl wärmt die Seele und füllt die Wampe!', '[{"kategorie": "wörtlich", "text": "\"Ein wohlschmeckendes Mahl nährt den Leib und tröstet die Seele!\"  2. Ein leckeres Essen macht satt und zufrieden!  3. Ein feine Mahlzeit macht den Bauch voll und das Herz froh!"}]'::jsonb, ''),
  ('a-guats-bappi-des-haumma-si-jetzt-vadiind', 'A guats Bappi, des haumma si jetzt vadiind!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Ein gutes Papperl, das haben wir uns jetzt verdient!', '[{"kategorie": "wörtlich", "text": "\"Eine feine Mahlzeit - die haben wir uns wohl verdient!\"  2. So, jetzt kommt ein anständiger Schmaus – den haben wir uns auch verdient!  3. Ein Schmankerl zur Belohnung – genau das haben wir uns verdient!"}]'::jsonb, ''),
  ('so-jetzd-tua-ma-moi-wos-guads-bappaln-und-daunn-gemma-olle-zsaumm-auf-laepschi', 'So, jetzd tua ma moi wos Guads bappaln, und daunn gemma olle zsaumm auf Läpschi!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'So, jetzt tun wir mal was Gutes bapperln, und dann gehen wir alle zusammen auf Lepschi!', '[{"kategorie": "wörtlich", "text": "\"So, jetzt lasst uns mal was Gutes speisen, und dann gehen wir alle zusammen auf Streifzug durch die Nacht!\"  2. So, jetzt gönnen wir uns mal ein gutes Essen, und dann machen wir uns alle zusammen auf den Weg ins Vergnügen!  3. So, jetzt mampfen wir mal was Ordentliches, und danach machen wir alle gemeinsam Party bis spät in die Nacht!"}]'::jsonb, ''),
  ('paappad-woars-schoo-ois-klaanes-kind-owa-jetzd-hods-ia-mundweak-iwahaupt-ned-mea-unta-kontrolle', 'Paappad woars schoo ois klaanes Kind, owa jetzd hods ia Mundweak iwahaupt ned mea unta Kontrolle!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Pappert war sie schon als kleines Kind, aber jetzt hat sie ihr Mundwerk überhaupt nicht mehr unter Kontrolle!', '[{"kategorie": "wörtlich", "text": "\"Maulfrech war sie schon als kleines Kind, aber jetzt hat sie ihr Mundwerk überhaupt nicht mehr unter Kontrolle!\"  2. Die war früher ein Mundwerk mit Kind dran – heute ist sie nur noch Mundwerk!  3. Als Kind hatte sie schon eine große Klappe, aber jetzt kennt sie überhaupt keine Grenzen mehr!"}]'::jsonb, ''),
  ('hoid-de-pappn', 'Hoid de Pappn!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Halt die Pappen!', '[{"kategorie": "wörtlich", "text": "\"Halt den Mund!\"  2. \"Halt''s [[Maul]]!\"  3. [[Hoid de Goschn!]]  4. \"Halt die Klappe!\"  5. \"Sei [[kusch]]!\""}]'::jsonb, ''),
  ('hoid-de-pappn-goschata-bua', 'Hoid de Pappn, goschata Bua!', '', '', '', 'Schimpfen und Fluchen auf Wienerisch', 'Halt die Pappen, goscherter Bub!', '[{"kategorie": "wörtlich", "text": "\"Halt den Mund, du vorlautes Bürschchen!\"  2. \"Halt den Mund, du frecher Bengel!\"  3. \"Halt die Klappe, du vorlaute Rotznase!\""}]'::jsonb, ''),
  ('imma-de-pappn-offn-haum', 'imma de Pappn offn haum', '', '', '', 'Wiener Sprüche, die sitzen!', 'immer die Pappen offen haben', '[{"kategorie": "wörtlich", "text": "\"ständig den Mund offen haben\""}, {"kategorie": "", "text": "\"immerzu das Maul aufreißen\""}, {"kategorie": "", "text": "\"ständig am Quatschen sein\""}, {"kategorie": "", "text": "\"sich ständig einmischen\""}, {"kategorie": "", "text": "\"nie die Klappe halten können\""}]'::jsonb, 'Dea hod imma de Pappn offn, obwoira von nix a Aunung hod!'),
  ('dea-hod-imma-de-pappn-offn-obwoira-von-nix-a-aunung-hod', 'Dea hod imma de Pappn offn, obwoira von nix a Aunung hod!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Der hat immer die Pappen offen, obwohl er von nichts eine Ahnung hat!', '[{"kategorie": "wörtlich", "text": "\"Der reißt ständig das Maul auf, ohne überhaupt zu checken, worum’s geht!\"  2. Der ist ständig am Quatschen, hat aber von nichts eine Ahnung!  3. Die Fresse hat er immer weit offen, aber im Kopf nur Durchzug!"}]'::jsonb, 'imma de Pappn offn haum'),
  ('wem-aane-ind-pappen-haun', 'wem aane ind Pappen haun', '', '', '', 'Wiener Sprüche, die sitzen!', 'jemandem eine in die Pappen hauen', '[{"kategorie": "wörtlich", "text": "\"jemandem eine aufs Maul hauen\""}, {"kategorie": "", "text": "\"jemandem eins auf die Fresse geben\""}, {"kategorie": "", "text": "\"jemandem eins auf die Schnauze hauen\""}, {"kategorie": "", "text": "\"jemandem eine Maulschelle verpassen\""}]'::jsonb, ''),
  ('no-so-a-schbruch-oida-und-i-hau-da-aane-ind-pappn-und-zwoa-gratis', 'No so a Schbruch, Oida, und I hau da aane ind Pappn - und zwoa gratis!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Noch so ein Spruch, Alter, und ich hau dir eine in die Pappen - und zwar gratis!', '[{"kategorie": "wörtlich", "text": "\"Noch so ein Spruch, Alter, und ich hau dir eine aufs Maul - und zwar gratis!\"  2. Pass auf, Alter – noch so’n Spruch, und du kassierst eine Maulschelle deluxe - auf Haus!  3. Red noch einmal so dumm daher, und du hast gleich gratis die Faust im Maul, Alter!"}]'::jsonb, 'wem aane ind Pappen haun'),
  ('de-pappn-aufreissn', 'de Pappn aufreissn', '', '', '', 'Wiener Sprüche, die sitzen!', 'die Pappen aufreißen', '[{"kategorie": "wörtlich", "text": "\"das Maul aufreißen\""}, {"kategorie": "", "text": "\"große Töne spucken\""}, {"kategorie": "", "text": "\"die Schnauze aufreißen\""}, {"kategorie": "", "text": "\"das große Wort schwingen\""}]'::jsonb, 'Waunn dea Typ do no amoi so de Pappn aufreissd, kriagda Post von meina Faust!'),
  ('waunn-dea-typ-do-no-amoi-so-de-pappn-aufreissd-kriagda-post-von-meina-faust', 'Waunn dea Typ do no amoi so de Pappn aufreissd, kriagda Post von meina Faust!', '', '', '', 'Wiener Gaunersprache', 'Wenn der Typ da noch einmal so die Pappen aufreißt, kriegt er Post von meiner Faust!', '[{"kategorie": "wörtlich", "text": "\"Wenn der Typ noch einmal so das Maul aufreißt, kriegt er Post von meiner Faust!\"  2. Wenn der Typ noch einmal die Fresse so weit aufreißt, frisst er meine Faust!  3. Der soll bloß nicht weiter die Schnauze aufreißen – sonst zieh ich ihm eine übers Maul, dass ihm die Ohren klingeln!"}]'::jsonb, 'de Pappn aufreissn'),
  ('i-bin-mit-aana-deaoatign-fueuezpappn-aufgwochd-dass-ma-de-zungan-aum-gaumen-festpickd-is', 'I bin mit aana deaoatign Füüzpappn aufgwochd, dass ma de Zungan aum Gaumen festpickd is!', '', '', '', 'Krank & kuriert auf Wienerisch', 'Ich bin mit einer derartigen Filzpappen aufgewacht, dass mir die Zunge am Gaumen festgeklebt ist!', '[{"kategorie": "wörtlich", "text": "\"Ich bin mit so einem trockenen Mund aufgewacht, dass mir die Zunge am Gaumen festgeklebt ist!\"  2. Ich bin aufgewacht mit einer Goschen wie Sandpapier – die Zunge war mir fast am Gaumen angewachsen!  3. Ich bin mit einer total trockenen Goschen aufgewacht - mein ganzer Speichel war in der Nacht verdunstet!"}]'::jsonb, ''),
  ('de-wixa-haum-mi-haenga-lossn-muttasoeoenallaanich-vuam-puff-oone-tschik-und-oone-kaesch', 'De Wixa haum mi hänga lossn - muttasöönallaanich vuam Puff, oone Tschik und oone Käsch!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Die Wichser haben mich hängen lassen – mutterseelenallein vor dem Puff, ohne Tschick und ohne Cash!', '[{"kategorie": "wörtlich", "text": "\"Die Wichser haben mich hängen lassen – mutterseelenallein vor dem Puff, ohne Kippe, ohne Cash!\"  2. Die Penner haben mich eiskalt sitzen lassen – ganz allein vor’m Puff, kein Glimmstängel, kein Geld, und Frost bis unter die Eier!  3. Diese Spackos haben mich schön verrecken lassen – mutterseelenallein vor’m Bordell, klamme Taschen, trockene Kehle!"}]'::jsonb, ''),
  ('da-pappnakrobat-is-wiida-aum-schdart-groosse-goschn-nix-dahinta', 'Da Pappnakrobat is wiida aum Schdart - groosse Goschn, nix dahinta!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Der Pappenakrobat ist wieder am Start – große Goschen, nix dahinter!', '[{"kategorie": "wörtlich", "text": "\"Der Phrasendrescher ist wieder am Start – große Fresse, nix dahinter!\"  2. Der Maulheld vom Dienst ist wieder in Action – Fresse aufreißen kann er, liefern nicht!  3. Der Kasperl mit der Dauerpappulatur ist wieder da – wie immer nur heiße Luft im Getriebe!"}]'::jsonb, ''),
  ('kenntad-dem-daumpfplaudara-do-vuan-endlich-moi-wea-in-schdecka-ziang', 'Kenntad dem Daumpfplaudara do vuan endlich moi wea in Schdecka ziang?', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Könnte dem Dampfplauderer da vorne endlich mal wer den Stecker ziehen?', '[{"kategorie": "wörtlich", "text": "\"Kann mal einer dem Phrasendrescher da vorne endlich den Stecker ziehen?\"  2. Könnte mal jemand dem Fassadenschwätzer da vorne das Maul zukleben, bevor uns allen die Ohren bluten?  3. Hey, wer zieht dem Schaumschläger da vorne endlich den Stecker, bevor er sich selbst noch applaudiert?"}]'::jsonb, ''),
  ('ois-fremda-host-imma-scho-gschdaund-mit-woeoechana-leichtigkeit-de-pariisa-reedn-schdreidn-und-lochn', 'Ois Fremda host imma scho gschdaund, mit wööchana Leichtigkeit de Pariisa reedn, schdreidn und lochn!', '', '', '', 'Wiener Wörter mit schillernder Geschichte', 'Als Fremder hast du schon immer über die Leichtigkeit gestaunt, mit der die Pariser reden, streiten und lachen!', '[{"kategorie": "wörtlich", "text": "\"Als Außenstehender hast du immer schon bewundert, wie mühelos die Pariser miteinander sprechen, streiten und lachen!\"  2. \"Schon immer fiel einem als Fremdem die Leichtigkeit auf, mit der die Pariser miteinander umgehen!\"  3. \"Jedem Fremden von einst und jetzt fällt auf, wie ungezwungen die Pariser miteinander sprechen, diskutieren und lachen!\""}]'::jsonb, ''),
  ('leeg-ma-noo-zwaa-scheim-pariisa-aufd-semmae-owa-schee-dinn', 'Leeg ma noo zwaa Scheim Pariisa aufd Semmä - owa schee dinn!', '', '', '', 'Wiener Fleischhauer-Slang', 'Leg mir noch zwei Scheiben Pariser auf die Semmel, aber schön dünn!', '[{"kategorie": "wörtlich", "text": "\"Leg mir noch zwei Scheiben Pariser Wurst aufs Brötchen, aber schön dünn!\"  2. Gib mir noch ein bisschen was von der feinen Fleischwurst – schön dünn geschnitten!  3. Noch ein paar feine Scheiben von der Wurst, ja? Kommt direkt aufs Brötchen!"}]'::jsonb, ''),
  ('hostn-pariisa-dabei', 'Hostn Pariisa dabei?', '', '', '', 'Wiener Jugendsprache & Teenie-Talk', 'Hast du ''n Pariser dabei?', '[{"kategorie": "wörtlich", "text": "\"Hast ’n Gummi am Start?\"  2. \"Hast du ein Kondom eingesteckt?\"  3. \"Hast du ein Verhüterli dabei?\""}]'::jsonb, ''),
  ('waunn-i-moi-schdiab-soins-de-easchde-paarte-auf-mein-schdaummtisch-leeng', 'Waunn I moi schdiab, soins de easchde Paarte auf mein Schdaummtisch leeng!', '', '', '', 'Tod und Sterben auf Wienerisch', 'Wenn ich mal sterbe, sollen sie die erste Parte auf meinen Stammtisch legen!', '[{"kategorie": "wörtlich", "text": "\"Wenn''s mich einmal erwischt, soll der Wirt die erste Parte auf meinem Stammtisch auflegen!\"  2. Wenn mein letzter Vorhang fällt, dann möge der Wirt meine Parte zuerst dorthin tragen, wo mein Glas gestanden hat!  3. Meine Parte gehört nicht in die Zeitung – sondern auf den Stammtisch!"}]'::jsonb, ''),
  ('haengds-mei-bataazl-ned-bei-da-kiachn-sondan-beim-wiaschdlschdaund-auf-waeu-duat-is-des-woare-leebm-dahaam', 'Hängds mei Bataazl ned bei da Kiachn, sondan beim Wiaschdlschdaund auf - wäu duat is des woare Leebm dahaam!', '', '', '', 'Tod und Sterben auf Wienerisch', 'Hängt mein Partatzel nicht bei der Kirche auf, sondern beim Würstelstand – weil dort ist das wahre Leben daheim!', '[{"kategorie": "wörtlich", "text": "\"Spart euch den Kirchenkasten und hängt meinen Partezettel lieber am Würstelstand auf - denn dort spielt sich das wahre Leben ab!\"  2. Pickt meine Todesanzeige statt an die Kirchenwand lieber an den Würstelstand – da kriegt ich mehr Abgangsapplaus!  3. Meine Parte soll dort hängen, wo der Senf tropft, nicht der Weihrauch!"}]'::jsonb, ''),
  ('waunn-i-moi-in-leffae-oogib-daunn-haengds-mein-paartezeedl-ned-vua-da-kiachn-sondan-aum-wiaschdlschdandl-auf-waeu-duat-trauan-d-leit-ealich', 'Waunn I moi in Leffä oogib, daunn hängds mein Paartezeedl ned vua da Kiachn, sondan aum Wiaschdlschdandl auf - wäu duat trauan d''Leit ealich!', '', '', '', 'Tod und Sterben auf Wienerisch', 'Wenn ich einmal den Löffel abgebe, dann hängt meinen Partezettel nicht vor der Kirche, sondern am Würstelstand auf - weil dort trauern die Leute ehrlich!', '[{"kategorie": "wörtlich", "text": "\"Wenn ich einmal ins Gras beiße, dann hängt meine Todesanzeige nicht am Schwarzen Brett, sondern am Würstelstand aus – denn dort wird noch aufrichtig getrauert!\" 2. Wenn ich mal die Patschen strecke, dann trauert nicht in der Kirche, sondern beim Würstelstand um mich – da ist die Anteilnahme ehrlicher!  3. Mein Partezettel wird nicht in der Kirche, sondern am Würstelstand hängen - da weint man nicht, da denkt man mit Freude zurück!"}]'::jsonb, ''),
  ('de-partii-woa-so-untaiadisch-wia-haedn-unsa-goeoed-zruckvalaunga-soin', 'De Partii woa so untaiadisch, wia hädn unsa Gööd zruckvalaunga soin!', '', '', '', 'Wiener Fußballer- und Sportlerjargon', 'Die Partie war so unterirdisc h, wir hätten unser Geld zurückverlangen sollen!', '[{"kategorie": "wörtlich", "text": "\"Das Spiel war so schwach, man hätte sein Eintrittsgeld zurückverlangen sollen!\"  2. Das Spiel war grottenschlecht - dafür noch Eintritt zahlen, ist eine Frechheit!  3. Die Begegnung war derart enttäuschend, dass man sein Geld zurückfordern sollte!"}]'::jsonb, ''),
  ('de-easchde-partii-is-schoo-vakaufd-de-zweite-kummd-daunn-naechste-wochn', 'De easchde Partii is schoo vakaufd, de zweite kummd daunn nächste Wochn!', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'Die erste Partie ist schon verkauft, die zweite kommt dann nächste Woche!', '[{"kategorie": "wörtlich", "text": "\"Die erste Charge ist ausverkauft, Nachschub kommt dann nächste Woche!\"  2. Die erste Lieferung ist bereits vergriffen, die nächste wird dann kommende Woche erwartet!  3. Die Erstpartie ist bereits vollständig verkauft. Eine weitere Lieferung kommt dann voraussichtlich nächste Woche!"}]'::jsonb, ''),
  ('kumm-schoo-a-letzde-partii-geed-noo-daunn-moch-ma-schluss-fia-heit', 'Kumm schoo, a letzde Partii geed noo - daunn moch ma Schluss fia heit!', '', '', '', 'Wiener Kartentipplerjargon', 'Komm schon, eine letzte Partie geht noch – dann machen wir Schluss für heute!', '[{"kategorie": "wörtlich", "text": "\"Komm schon, eine Runde geht noch - dann lassen wir’s gut sein für heute!\"  2. Komm schon, noch ein allerletztes Spielchen - dann machen wir den Deckel drauf!  3. Los, komm schon, eine allerletzte Runde - dann ist Schicht im Schacht!"}]'::jsonb, ''),
  ('ea-und-sii-mochn-a-laundpartii', 'Ea und sii mochn a Laundpartii!', '', '', '', 'Wiener Kartentipplerjargon', 'Er und sie machen eine Landpartie', '[{"kategorie": "wörtlich", "text": "\"Er und sie fahren aufs Land!\"  2. (Kartenspielerjargon, [[Schnapsen]], scherzhaft für): \"Ich sage einen Zwanziger an!\" bzw. \"Ich sage einen Vierziger an!\" (d.h. \"Ich habe König und Dame derselben Farbe in der Hand, bin am Ausspielen und mache eine entsprechende Ansage\")"}]'::jsonb, ''),
  ('heit-gemma-auf-a-laundpartii', 'Heit gemma auf a Laundpartii!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Heute gehen wir auf eine Landpartie!', '[{"kategorie": "wörtlich", "text": "\"Heute fahren wir raus aufs Land!\"  2. \"Heute machen wir eine Spritztour ins Grüne!\"  3. Heute machen wir einen Trip in die Provinz!"}]'::jsonb, ''),
  ('heit-foama-aufs-laund', 'Heit foama aufs Laund!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Heute fahren wir aufs Land!', '[{"kategorie": "wörtlich", "text": "\"Heute fahren wir raus ins Grüne!\"  2. \"Heute machen wir eine [[Landpartie]]!\"  3. Heute machen wir einen Trip in die Provinz!"}]'::jsonb, ''),
  ('a-guade-partii', 'a guade Partii', '', '', '', 'Wiener Sprüche, die sitzen!', 'eine gute Partie', '[{"kategorie": "wörtlich", "text": "\"eine gute Partie auf dem Heiratsmarkt\""}, {"kategorie": "", "text": "\"ein/e attraktive/r Heiratskandidat/in\""}, {"kategorie": "", "text": "\"ein/e solide/r Partner/in für die Ehe\""}, {"kategorie": "", "text": "\"ein/e Top-Kandidat/in fürs Heiraten\""}]'::jsonb, 'Mitn fettn Eabe vom Opa isa jetzt auf amoi a guade Partii - friara woid owa kaane wos von eam wissen!'),
  ('mitn-fettn-eabe-vom-opa-isa-jetzt-auf-amoi-a-guade-partii-friara-woid-owa-kaane-wos-von-eam-wissen', 'Mitn fettn Eabe vom Opa isa jetzt auf amoi a guade Partii - friara woid owa kaane wos von eam wissen!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Mit dem fetten Erbe vom Opa ist er jetzt auf einmal eine gute Partie - früher wollte aber keine was von ihm wissen!', '[{"kategorie": "wörtlich", "text": "2. Kaum hat er Opas Kohle geerbt, reißen sich die Mädels plötzlich um ihn – vorher war er für alle nur Luft!  3. Früher war er der Typ, den man höchstens zum Umzug gerufen hat – jetzt mit dem Erbe vom Opa ist er auf einmal ''Mr. Right''!"}]'::jsonb, 'a guade Partii'),
  ('dea-is-a-guade-partii', 'Dea is a guade Partii!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Der ist eine gute Partie', '[{"kategorie": "wörtlich", "text": "\"Der ist ein attraktiver Heiratskandidat!\"  2. Der ist ein Top-Kandidat fürs Heiraten!  3. Der ist ein echter Mr. Right!"}]'::jsonb, ''),
  ('de-pfuschapartii-hod-mea-runiad-ois-repariad', 'De Pfuschapartii hod mea runiad ois repariad!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Die Pfuscherpartie hat mehr ruiniert als repariert!', '[{"kategorie": "wörtlich", "text": "\"Die Murkstruppe hat mehr ruiniert als repariert!\"  2. Diese Hinterhofkolonne hat mehr Löcher aufgerissen, als sie zugemacht haben!  3. Was die Chaostruppe da gemacht hat, ist keine Reparatur – das ist vorsätzliche Sachbeschädigung!"}]'::jsonb, ''),
  ('de-schwoazhacklapartii-woa-schnoella-weg-ois-de-hee-hod-schaun-kenna', 'De Schwoazhacklapartii woa schnölla weg, ois de Hee hod schaun kenna!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Die Schwarzhacklerpartie war schneller weg, als die Polizei hat gucken können!', '[{"kategorie": "wörtlich", "text": "\"Die Pfuschertruppe war schneller verschwunden, als die Polizei hat gucken können!\"  2. Die Schwarzarbeitertruppe hat sich schneller aus dem Staub gemacht, als die Finanzpolizei überhaupt hat reagieren können!  3. Die Pfuscherpartie ist abgehauen, noch bevor die Polente überhaupt ausgestiegen ist!"}]'::jsonb, ''),
  ('in-schdiangaufgaung-hob-i-ma-von-schwoazhackla-baun-lossen-jetzd-brauch-i-a-beagschdeigaausruestung-waunn-i-ins-schlofzimma-wueue', 'In Schdiangaufgaung hob I ma von Schwoazhackla baun lossen - jetzd brauch I a Beagschdeigaausrüstung, waunn I ins Schlofzimma wüü!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Den Stiegenaufgang hab ich mir von Schwarzhacklern bauen lassen - jetzt brauch ich ''ne Bergsteigerausrüstung, wenn ich ins Schlafzimmer will!', '[{"kategorie": "wörtlich", "text": "\"Die Treppe hab ich mir von Pfuschern bauen lassen – jetzt ist sie so steil, dass ich ''ne Bergsteigerausrüstung brauch, um bis ins Schlafzimmer zu gelangen!\"  2. Die Schwarzarbeiter haben mir den Stiegenaufgang so steil hingezimmert, dass ich Seil und Haken brauch, um hochzukommen!  3. Der Stiegenaufgang von der Schwarzarbeiterpartie schaut aus wie ’n Hochseilgarten - ich fühl ich mich jedes Mal wie Reinhold Messner, wenn ich ins Bett will!"}]'::jsonb, ''),
  ('des-woara-schwaare-partii', 'Des woara schwaare Partii!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Das war eine schwere Partie', '[{"kategorie": "wörtlich", "text": "\"Das war alles andere als ein Spaziergang!\"  2. \"Das war ein schwieiriges Unterfangen!\"  3. \"Das war eine heikle Mission!\""}]'::jsonb, ''),
  ('waunn-a-partii-so-hinta-dia-schdeed-daunn-mochd-an-des-schdoiz', 'Waunn a Partii so hinta dia schdeed, daunn mochd an des schdoiz!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Wenn eine Partie so hinter dir steht, dann macht einen das stolz!', '[{"kategorie": "wörtlich", "text": "\"Wenn die eigene Mannschaft so geschlossen hinter dir steht, dann macht einen das stolz!\"  2. Wenn ein Team so hinter dir steht, erfüllt dich das mit Stolz!  3. Wenn die ganze Truppe so geschlossen zu dir hält, dann stehst du zehn Meter größer da!"}]'::jsonb, ''),
  ('de-partii-aufhoidn', 'de Partii aufhoidn', '', '', '', 'Wiener Sprüche, die sitzen!', 'die Partie aufhalten', '[{"kategorie": "wörtlich", "text": "\"die Truppe aufhalten\""}, {"kategorie": "fig.", "text": "\"den ganzen Laden aufhalten\""}, {"kategorie": "", "text": "\"den Troß lahmlegen\""}, {"kategorie": "", "text": "\"den Pulk aufhalten\""}]'::jsonb, 'Da Waumpade do vuan hoid de gaunze Partii auf - dea keichd wiara hiinnichs Mopal!'),
  ('da-waumpade-do-vuan-hoid-de-gaunze-partii-auf-dea-keichd-wiara-hiinnichs-mopal', 'Da Waumpade do vuan hoid de gaunze Partii auf - dea keichd wiara hiinnichs Mopal!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Der Wamperte da vorne hält die ganze Partie auf - der keucht wie ein kaputtes Moped!', '[{"kategorie": "wörtlich", "text": "\"Der Fettwanst da vorne hält die ganze Truppe auf - der keucht wie ein kaputtes Moped!\"  2. Der Fettsack da vorne bremst den ganzen Tross – der schnauft ja wie ''ne alte Lok!  3. Der Blade da vorne hält den ganzen Laden auf - der röchelt ja wie ein rostiger Rasenmäher!"}]'::jsonb, ''),
  ('de-gschdopfde-obtaeulung', 'de gschdopfde Obtäulung', '', '', '', 'Wiener Sprüche, die sitzen!', 'die gestopfte Abteilung', '[{"kategorie": "wörtlich", "text": "\"die Reichenabteilung\" (\"die mit Geldscheinen vollgestopfte Clique\")"}, {"kategorie": "allg.", "text": "\"Reichenfraktion, \"Schicki-Micki-Truppe\", \"High-Society-Partie\", \"Bonzenbande\", \"Schickeria\", \"feine Gesellschaft\", [[Hautevolée]]"}]'::jsonb, 'Des is aana von da gschdopfdn Obtäulung - dea scheissd Gööd und waass ned, wohii damit!'),
  ('des-is-aana-von-da-gschdopfdn-obtaeulung-dea-scheissd-goeoed-und-waass-ned-wohii-damit', 'Des is aana von da gschdopfdn Obtäulung - dea scheissd Gööd und waass ned, wohii damit!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Das ist einer von der gestopften Abteilung - der scheißt Geld und weiß nicht, wohin damit!', '[{"kategorie": "wörtlich", "text": "\"Das ist einer von der Reichenfraktion - der scheißt Geld und weiß nicht, wohin damit!\"  2. Das ist einer von der High-Society-Partie – dem hängt die Kohle aus den Taschen und er weiß nicht, wohin damit!  3. Das ist einer von der Bonzenbande – der scheißt Kohle und wischt sich mit Hunderten den Arsch aus!"}]'::jsonb, 'de gschdopfde Obtäulung'),
  ('de-gschdopfde-bagaasch', 'de gschdopfde Bagaasch', '', '', '', 'Schimpfen und Fluchen auf Wienerisch', 'die gestopfte Bagage', '[{"kategorie": "wörtlich", "text": "\"das Reichenpack\" (\"das mit Geldscheinen vollgestopfte Lumpenpack\")"}, {"kategorie": "allg.", "text": "\"Reichenclan\", \"Reichengesindel, \"Schicki-Micki-Truppe\", \"Gucci-Gang\", \"Bonzenbande\", \"Kaviar-Clique\", [[Hautevolée]]"}]'::jsonb, 'Waunn mei Schwiigamuada mid iara gschdopfdn Bagaasch auroid, vaschdeck I mi im Kölla!'),
  ('waunn-mei-schwiigamuada-mid-iara-gschdopfdn-bagaasch-auroid-vaschdeck-i-mi-im-koella', 'Waunn mei Schwiigamuada mid iara gschdopfdn Bagaasch auroid, vaschdeck I mi im Kölla!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Wenn meine Schwiegermutter mit ihrer gestopften Bagage anrollt, verstecke ich mich im Keller!', '[{"kategorie": "wörtlich", "text": "\"Wenn meine Schwiegermutter mit ihrer Schicki-Micki-Truppe anrollt, geh ich in Deckung!\"  2. Wenn meine Schwiegermutter mit ihrer Kaviar-Clique anrückt, such ich das Weite!  3. Wenn meine Schwiegermutter mit ihrer Gucci-Gang einmarschiert, flüchte ich in den Keller!"}]'::jsonb, 'de gschdopfde Bagaasch'),
  ('de-gschdopfde-partii', 'de gschdopfde Partii', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'die gestopfte Partie', '[{"kategorie": "wörtlich", "text": "\"die Reichenfraktion\" (\"die mit Geldscheinen vollgestopfte Clique\")"}, {"kategorie": "allg.", "text": "\"Schicki-Micki-Truppe\", \"High-Society-Partie\", \"Bonzenbande\", \"Schickeria\", \"feine Gesellschaft\", [[Hautevolée]]"}]'::jsonb, 'De gschdopfde Partii hockd do vuan, frissd Kaviaa und scheissd Gööd wiar aundare Kneedln!'),
  ('de-gschdopfde-partii-hockd-do-vuan-frissd-kaviaa-und-scheissd-goeoed-wiar-aundare-kneedln', 'De gschdopfde Partii hockd do vuan, frissd Kaviaa und scheissd Gööd wiar aundare Kneedln!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Die gestopfte Partie hockt da vorne, frisst Kaviar und scheißt Geld wie andere Knödel!', '[{"kategorie": "wörtlich", "text": "\"Die Schicki-Micki-Truppe sitzt da vorne, frisst Kaviar und scheißt Geld wie andere Knödel!\"  2. Die feine Gesellschaft sitzt da vorne, isst Kaviar und protzt mit ihrem Reichtum!  3. Die Schickeria hockt da vorne, haut sich den Kaviar rein und kackt Geldscheine wie andere Knödel!"}]'::jsonb, 'de gschdopfde Partii'),
  ('nau-ees-seids-ma-a-leiwaunde-partii', 'Nau, ees seids ma a leiwaunde Partii!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Na, ihr seid mir eine leiwande Partie', '[{"kategorie": "wörtlich", "text": "\"Na, ihr seid mir aber eine Gaudi-Truppe!\"  2. (ironisch): \"Na, ihr seid mir ja ein echtes Traumteam!\"  3. \"Na, ihr seid mir aber eine schräge Truppe!\"  4. \"Na, ihr seid mir aber ein skurriler Haufen!\""}]'::jsonb, ''),
  ('de-buama-san-a-zsaummgschwassde-waunsinnspartii-de-fressn-in-geegna-aum-plotz-mit-haut-und-hoa', 'De Buama san a zsaummgschwassde Waunsinnspartii - de fressn in Geegna aum Plotz mit Haut und Hoa!', '', '', '', 'Wiener Fußballer- und Sportlerjargon', 'Die Buben sind eine zusammengeschweißte Wahnsinnspartie - die fressen den Gegner auf''m Platz mit Haut und Haaren!', '[{"kategorie": "wörtlich", "text": "\"Die Jungs sind ein zusammengeschweißtes Spitzenteam - die fressen den Gegner auf''m Platz mit Haut und Haaren!\"  2. Die Jungs sind eine top eingespielte Spitzenmannschaft – sie spielen den Gegner förmlich an die Wand!  3. Das ist eine eingeschworene Truppe – die hauen den Gegner gnadenlos weg!"}]'::jsonb, ''),
  ('des-woara-waunsinnspartii-tempo-tore-dramatik-ollas-dabei', 'Des woara Waunsinnspartii - Tempo, Tore, Dramatik, ollas dabei!', '', '', '', 'Wiener Fußballer- und Sportlerjargon', 'Das war ein Wahnsinnsspiel – Tempo, Tore, Dramatik, alles dabei!', '[{"kategorie": "wörtlich", "text": "\"Das war ein absolutes Spitzenspiel – Tempo, Tore, Dramatik, alles dabei!\"  2. Das war ein Mörderkick – Tore, Tempo, Wahnsinn ohne Ende!  3. Das war ein echtes Topspiel – Tore, Drama, Herzrasen, Wahnsinn!"}]'::jsonb, ''),
  ('geegn-so-a-wiatshauspartii-deafsd-aafoch-ned-valian', 'Geegn so a Wiatshauspartii deafsd aafoch ned valian!', '', '', '', 'Wiener Fußballer- und Sportlerjargon', 'Gegen so eine Wirtshauspartie darfst du einfach nicht verlieren!', '[{"kategorie": "wörtlich", "text": "\"Gegen so eine Stammtischtruppe darfst du nicht verlieren!\"  2. Gegen so eine Gurkentruppe darf man einfach keine Punkte herschenken!  3. Wer gegen so ein Eierteam verliert, macht sich zum Affen!"}]'::jsonb, ''),
  ('des-woa-ka-fuassboischbueue-des-woara-wiatshauspartii-mit-drei-promueue', 'Des woa ka Fuassboischbüü - des woara Wiatshauspartii mit drei Promüü!', '', '', '', 'Wiener Fußballer- und Sportlerjargon', 'Das war kein Fußballspiel - das war eine Wirtshauspartie mit drei Promille!', '[{"kategorie": "wörtlich", "text": "\"Das war kein Fußballspiel - das war ein Wirtshauskick mit drei Promille!\"  2. Das war kein ernstzunehmendes Spiel – das war eine Schlafwagenpartie!  3. Das war ein unterirdisches Fußballmatch - – Tempo null, Technik minus zehn!"}]'::jsonb, ''),
  ('na-supa-mit-dea-ziidarapartii-weama-kaa-maetsch-gwinna', 'Na supa, mit dea Ziidarapartii weama kaa Mätsch gwinna!', '', '', '', 'Wiener Fußballer- und Sportlerjargon', 'Na super, mit dieser Zittererpartie werden wir kein Match gewinnen!', '[{"kategorie": "wörtlich", "text": "\"Na toll, mit dieser Angsthasentruppe werden wir kein Match gewinnen!\"   2. Na Klasse, mit dieser Truppe von lauter Schissern haben wir keine Chance auf den Sieg!  3. Na wunderbar – mit so einer ängstlichen Mannschaft brauchen wir gar nicht erst antreten!"}]'::jsonb, ''),
  ('heast-boss-mit-so-ana-fedarantnpartii-daed-i-ned-amoi-in-an-wiaschlschdaund-eibrechn-gee', 'Heast Boss, mit so ana Fedarantnpartii däd I ned amoi in an Wiaschlschdaund eibrechn gee!', '', '', '', 'Wiener Gaunersprache', 'Hey Boss, mit so einer Federantenpartie tät ich nicht mal in ''nen Würstelstand einbrechen gehen!', '[{"kategorie": "wörtlich", "text": "\"Hey Boss, mit so ’ner Angsthasentruppe geh ich nich mal in ’nen Würtselstand einbrechen!\"  2. Hör mal, Boss, mit diesem Haufen von Schissern mach ich höchstens ’n Joghurt auf – wenn überhaupt!  3. Ey Chef, mit dieser Ansammlung von lauter Schissern geh ich nicht mal ''nen Kios knacken!"}]'::jsonb, ''),
  ('meine-neichn-oaweidskolleeng-san-olle-a-echte-bschissalpartii-soboids-eanst-wiad-zaad-jeeda-in-schwaaf-ei', 'Meine neichn Oaweidskolleeng san olle a echte Bschissalpartii - soboids eanst wiad, zaad jeeda in Schwaaf ei!', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'Meine neuen Arbeitskollegen sind alle eine echte Bschisserlpartie - sobald''s ernst wird, ziehen alle den Schweif ein!', '[{"kategorie": "wörtlich", "text": "\"Meine neuen Arbeitskollegen sind durch die Bank eine Angsthasentruppe - sobald''s ernst wird, ziehen alle den Schwanz ein!\"  2. Meine neuen Kollegen sind alle ziemliche Schisser – sobald’s brenzlig wird, verkriechen sie sich hinter ihrem Schreibtisch!  3. Meine neuen Kollegen sind eine echte Hosenscheißertruppe - kaum wird’s kritisch, ziehen sie alle ihre Köpfe ein wie feige Schildkröten!"}]'::jsonb, ''),
  ('buubalpartii-des-san-de-tschoppaln-im-parlament-de-noch-drei-instagram-storis-denkn-se-san-reif-fias-aussnministerium', 'Buubalpartii - des san de Tschoppaln im Parlament, de noch drei Instagram-Storis denkn, se san reif fias Aussnministerium!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Buberlpartie – das sind die Tschopperln im Parlament, die nach drei Instagram-Stories denken, sie sind reif fürs Außenministerium!', '[{"kategorie": "wörtlich", "text": "\"Buberlpartie – das sind die Jungpolitiker im Parlament, die nach drei Instagram-Stories denken, sie seien bereit fürs Außenministerium!\"  2. Buberlpartie – das Etikett für jene Jungpolitiker, die mit Soc+C6347ial-Media-Skills glänzen, aber ohne ihre politischen Seilschaften völlig hilflos sind!  3. Buberlpartie? Klar – die glauben, ein Praktikum beim Parteiboss und 5k Insta-Follower reichen für die Weltpolitik!"}]'::jsonb, ''),
  ('mia-san-a-woeoedpartii', 'Mia san a Wöödpartii!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Wir sind ''ne Weltpartie', '[{"kategorie": "wörtlich, Titel eines Songs von Horst Chmela", "text": "\"Wir sind ein Weltklasseteam!\"  2. Wir sind eine unschlagbare Truppe!  3. Wir sind eine eingeschworenes Team!"}]'::jsonb, ''),
  ('jeedn-freitog-treff-ma-uns-auf-a-gepfleegde-koatnpartie-beim-wiatn-dahaam-bei-meina-oidn-bin-i-daunn-easchd-wiida-aum-saumstog', 'Jeedn Freitog treff ma uns auf a gepfleegde Koatnpartie beim Wiatn - dahaam bei meina Oidn bin I daunn easchd wiida aum Saumstog!', '', '', '', 'Wiener Kartentipplerjargon', 'Jeden Freitag treffen wir uns auf eine gepflegte Kartenpartie beim Wirten - daheim bei meiner Alten bin ich dann erst wieder am Samstag!', '[{"kategorie": "wörtlich", "text": "\"Jeden Freitagabend treffen wir uns auf eine gepflegte Kartenrunde beim Wirten - heim zu meiner Alten komm ich dann erst wieder am Samstag!\"  2. Beim Wirt wird am Freitag nicht diskutiert, sondern Karten gespielt – und heim komm ich dann erst wieder, wenn der Hahn kräht!  3. Freitagabends pflegen wir unsere Kartenrunde im Gasthaus – und der Rückweg nach Hause zu meiner Alten führt dann meistens direkt zum Frühstückstisch!"}]'::jsonb, ''),
  ('valian-vabootn-des-is-a-schnittpartii-oida', 'Valian vabootn - des is a Schnittpartii, Oida!', '', '', '', 'Wiener Fußballer- und Sportlerjargon', 'Verlieren verboten – das ist ''ne Schnittpartie, Alter!', '[{"kategorie": "wörtlich", "text": "\"Verlieren ist keine Option – das ist ein Sechs-Punkte-Spiel, Mann!\"  2. Alles oder nichts - das ist ein Entscheidungsspiel, Alter!  3. Wenn wir das verlieren, können wir einpacken – das ist ein Spiel auf Leben und Tod, Bruder!"}]'::jsonb, ''),
  ('do-schdeed-de-partii', 'Do schdeed de Partii!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Da steht die Partie!', '[{"kategorie": "wörtlich", "text": "\"Da steht die Partie!\""}, {"kategorie": "allg.", "text": "\"Hier bewegt sich nichts weiter!\";  \"Da geht nichts weiter!\"  \"Alles steht hier still wie festgenagelt!\""}, {"kategorie": "Fußballerjargon", "text": "\"Da steht der Laden!\";  \"Da herrscht Standfußball pur!\"  \"Da bewegt sich gar nix mehr!\""}]'::jsonb, 'De haums Tial zuagmochd, jetzt schdeed de Partii!'),
  ('de-haums-tial-zuagmochd-jetzt-schdeed-de-partii', 'De haums Tial zuagmochd, jetzt schdeed de Partii!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Die haben das Türl zugemacht, jetzt steht die Partie!', '[{"kategorie": "wörtlich", "text": "\"Die haben das Tor geschlossen, jetzt bewegt sich nichts mehr weiter!\"  2. Die haben hinten dichtgemacht – jetzt steht die ganze Truppe und kann nicht weiter!  3. Die haben den Eingang abgeriegelt – jetzt steht die ganze Menschenmenge wie festgenagelt und kommt nicht weiter!"}]'::jsonb, 'Do schdeed de Partii!'),
  ('waunn-dea-ned-mituntaschreibd-schdeed-de-partii', 'Waunn dea ned mituntaschreibd, schdeed de Partii!', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'Wenn der nicht mitunterschreibt, steht die Partie!', '[{"kategorie": "wörtlich", "text": "\"Wenn der nicht mitunterschreibt, herrscht Stillstand auf ganzer Linie!\"  2. Ohne ihn geht gar nichts - wenn er nicht mitunterschreibt, ist Ende im Gelände!  3. Ohne seine Unterschrift steht der ganze Laden still!"}]'::jsonb, 'Do schdeed de Partii!'),
  ('buaschn-wia-miassn-wiida-druck-mochn-sunst-schdeed-de-gaunze-partii', 'Buaschn, wia miassn wiida Druck mochn - sunst schdeed de gaunze Partii!', '', '', '', 'Wiener Fußballer- und Sportlerjargon', 'Burschen, wir müssen wieder Druck machen - sonst steht die ganze Partie!', '[{"kategorie": "wörtlich", "text": "\"Burschen, wir müssen wieder pressen - sonst herrscht Standfußball pur!\"  2. Jungs, wir müssen wieder draufgehen – sonst schläft uns das Spiel ein!  3. Jungs, wir müssen das Tempo wieder hochziehen, sonst steht der ganze Laden!"}]'::jsonb, 'Do schdeed de Partii!'),
  ('aus-an-schnoeoen-bia-is-a-laengare-schdeepartii-wuan', 'Aus an schnöön Bia is a längare Schdeepartii wuan!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Aus einem schnellen Bier ist eine längere Stehpartie geworden!', '[{"kategorie": "wörtlich", "text": "\"Aus einem schnellen Bier wurde eine nächtliche Stehparty an der Schank!\"  2. Nur eine kurze Stehrunde im Wirtshaus - und schwupps: eine halbe Nacht lang an der Schank!  3. Geplant war ein schneller Schluck – geworden ist’s ''ne ausgewachsene Stehrunde bis fünf Uhr früh!"}]'::jsonb, ''),
  ('des-woara-a-reine-schdeepartii-kaane-eia-kaane-ideen-goa-nix', 'Des woara a reine Schdeepartii - kaane Eia, kaane Ideen, goa nix!', '', '', '', 'Wiener Fußballer- und Sportlerjargon', 'Das war eine reine Stehpartie - keine Eier, keine Ideen, gar nichts!', '[{"kategorie": "wörtlich", "text": "\"Das war Schlafwagenfußball pur - keine Eier, keine Ideen, gar nichts!\"  2. Das war Standfußball vom Feinsten – null Mut, null Kreativität, null Herz!  3. Das war kein Fußballmatch, das war reines Ballgeschiebe – ohne Eier, ohne Geist, ohne alles!"}]'::jsonb, ''),
  ('de-schdeepartii-mit-da-koeoenarin-hinta-da-schaunk-woa-spaunnenda-ois-de-gaunze-nochd-mit-ia-in-da-harpfn', 'De Schdeepartii mit da Köönarin hinta da Schaunk woa spaunnenda ois de gaunze Nochd mit ia in da Harpfn!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Die Stehpartie mit der Kellnerin hinter der Schank war spannender als die ganze Nacht mit ihr in der Harpfen!', '[{"kategorie": "wörtlich", "text": "\"Der Quickie im Stehen mit der Kellnerin hinter der Schank war spannender als die ganze Nacht mit ihr im Bett!\"  2. Die Stehnummer mit der Kellnerin war heißer als jede Matratzenorgie daheim!  3. Der Stehfick mit der Kellnerin hinter der Schank hat mehr Feuer gehabt als die ganze Nacht mit ihr im Bett!"}]'::jsonb, ''),
  ('waunn-da-partiifiara-pfeifd-schbringd-de-gaunze-truppn', 'Waunn da Partiifiara pfeifd, schbringd de gaunze Truppn!', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'Wenn der Partieführer pfeift, springt die ganze Truppe!', '[{"kategorie": "wörtlich", "text": "\"Wenn der Vorarbeiter pfeift, springt die ganze Mannschaft!\"  2. Ein Pfiff vom Vorarbeiter, und die ganze Truppe marschiert!  3. Wenn der Partieführer pfeift, springt der ganze Tross!"}]'::jsonb, ''),
  ('ees-seids-a-nuudlpartii-von-hint-bis-vuan-nui-einsotz-nui-eia-nui-punkte', 'Ees seids a Nuudlpartii von hint bis vuan - nui Einsotz, nui Eia, nui Punkte!', '', '', '', 'Wiener Fußballer- und Sportlerjargon', 'Ihr seid eine Nudelpartie von hinten bis vorne - null Einsatz, null Eier, null Punkte!', '[{"kategorie": "wörtlich", "text": "\"Ihr seid eine Murkstruppe von hinten bis vorne - null Einsatz, null Eier, null Punkte!\"  2. Ihr seid ein Haufen Versager – kein Kampf, kein Wille, keine Punkte!  3. Ihr seid eine Wapplerpartie sondergleichen - kein Einsatz, keine Ideen, keine Punkte!"}]'::jsonb, ''),
  ('de-faeaens-san-frustriad-so-a-nuudlpartii-im-obschdiigskaumpf-wueue-kaana-seeng', 'De Fääns san frustriad - so a Nuudlpartii im Obschdiigskaumpf wüü kaana seeng!', '', '', '', 'Wiener Fußballer- und Sportlerjargon', 'Die Fans sind frustriert – so eine Nudelpartie im Abstiegskampf will keiner sehen!', '[{"kategorie": "wörtlich", "text": "\"Die Fans sind frustriert – so eine Murkspartie im Abstiegskampf will keiner sehen!\"  2. Die Anhänger sind restlos bedient – so einen Grottenkick im Abstiegskampf will keiner sehen!  3. Die Fans sind stocksauer – so ein Schlafwagenfußball geht im Abstiegskampf gar nicht!"}]'::jsonb, ''),
  ('buaschn-ees-seids-a-echte-muaksapartii-waachkochd-wia-nuudln-im-suppnhaeaefn', 'Buaschn, ees seids a echte Muaksapartii - waachkochd wia Nuudln im Suppnhääfn!', '', '', '', 'Wiener Fußballer- und Sportlerjargon', 'Burschen, ihr seid eine echte Murkserpartie - weichgekocht wie Nudeln im Suppenhäfen!', '[{"kategorie": "wörtlich", "text": "\"Burschen, ihr seid eine echte Murksertruppe - weichgekocht wie Nudeln im Suppentopf!\"  2. Jungs, ihr seid eine Versagertruppe – so lasch, da lacht euch jeder Gegner aus!  3. Burschen, ihr seid eine echte Wapplerpartie – ohne Biss, ohne Substanz, weichgeklopft wie ein Wiener Schnitzel vorm Panieren!"}]'::jsonb, ''),
  ('leidln-des-woara-a-totale-muakspartii-ees-hobds-eich-jo-komplett-haenga-lossn', 'Leidln, des woara a totale Muakspartii - ees hobds eich jo komplett hänga lossn!', '', '', '', 'Wiener Fußballer- und Sportlerjargon', 'Leute, das war eine totale Murkspartie – ihr habt euch ja komplett hängen lassen!', '[{"kategorie": "wörtlich", "text": "\"Leute, das war ein grottenschlechtes Spiel – ihr habt euch ja komplett hängen lassen!\"  2. Leute, das war ein grausamer Anti-Kick – keine Einsatzbereitschaft, keine Gegenwehr, kein Garnichts!  3. Leute, das war eine Schlafwagenpartie – ihr habt euch am Platz hängen lassen wie nasse Fetzen!"}]'::jsonb, ''),
  ('a-koellapartii-oone-rausch-is-wiara-heiricha-oone-breedljausn', 'A Köllapartii oone Rausch is wiara Heiricha oone Breedljausn!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Eine Kellerpartie ohne Rausch ist wie ein Heuriger ohne Brettljause!', '[{"kategorie": "wörtlich", "text": "\"Eine Kellergassen-Tour ohne Rausch ist wie ein Heuriger ohne Brettljause!\"  2. Ein Weinkellermarathon ohne Rausch ist wie ein Heuriger ohne Ziehharmonika und schiefe Gstanzln!  3. Eine Kellergassen-Tour ohne Rausch ist wie wie ein Fasching ohne Krapfen!"}]'::jsonb, ''),
  ('leidln-des-heit-is-a-echte-koellapartii-do-zoeoed-nua-kaumpf-kaa-technik', 'Leidln, des heit is a echte Köllapartii - do zööd nua Kaumpf, kaa Technik!', '', '', '', 'Wiener Fußballer- und Sportlerjargon', 'Leute, das heut ist ’ne echte Kellerpartie – da zählt nur Kampf, keine Technik!', '[{"kategorie": "wörtlich", "text": "\"Leute, das heute ist ein echtes Abstiegsderby – da ist kein Platz für Schönspielerei, da zählt einzig und allein nur nur Kampf und Einsatz!\"  2. Leute, das heute ist kein Fußballfest, das ist ein Kellerduell der ganz harten Sorte – da musst jeden Meter fressen!  3. Männer, das ist heute ein Abstiegsduell mit offenem Visier – hier zählt nur Kampf, Wille und Leidenschaft!"}]'::jsonb, ''),
  ('da-koffa-is-ma-z-schwaa-do-kriag-i-schoo-an-hexnschuss-beim-hiischaun', 'Da Koffa is ma z''schwaa - do kriag I schoo an Hexnschuss beim Hiischaun!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Der Koffer ist mir zu schwer - da krieg ich schon ''nen Hexenschuss beim Hinschauen!', '[{"kategorie": "wörtlich", "text": "\"Der Koffer ist mir viel zu schwer - da krieg ich schon  beim bloßen Hingucken ''nen Bandscheibenvorfall!\"  2. Der Koffer ist mir viel zu schwer - da reißt’s mir schon beim Hingucken das Kreuz durch!  3. Der Koffer ist mir echt zu schwer – allein beim Anheben knackts mir schon im Rücken!"}]'::jsonb, ''),
  ('wem-ane-poschn', 'wem ane poschn', '', '', '', 'Wiener Sprüche, die sitzen!', 'jemandem eine paschen', '[{"kategorie": "wörtlich", "text": "\"jemandem eine knallen\""}, {"kategorie": "", "text": "\"jemandem eine Ohrfeige geben\""}, {"kategorie": "", "text": "jemandem eine [[Watsche]] verpassen"}]'::jsonb, ''),
  ('de-poscha-san-friara-bei-nochd-und-neewae-iwad-beag-zoong-um-ia-woa-ins-laund-z-schmuggln', 'De Poscha san friara bei Nochd und Neewä iwad Beag zoong, um ia Woa ins Laund z''schmuggln!', '', '', '', 'Wiener Wörter mit schillernder Geschichte', 'Die Pascher sind früher bei Nacht und Nebel über die Berge gezogen, um ihre Waren ins Land zu schmuggeln!', '[{"kategorie": "wörtlich", "text": "\"Die Schwarzmarkthändler sind früher bei Nacht und Nebel über die Bergpässe gezogen, um ihre Waren ins Land zu schmuggeln!\"  2. Früher überquerten Schmuggler bei Nacht und Nebel die Bergpässe, um ihre Waren illegal ins Land zu bringen!  3. Die Pascher sind damals im Schutz der Dunkelheit mit Rucksäcken voller Schmuggelgut über die Pässe geschlichen - beladen mit Kaffee, Zigaretten und Schnaps!"}]'::jsonb, ''),
  ('do-hods-an-poscha-gmocht', 'Do hods an Poscha gmocht!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Da hat es einen Pascher gemacht!', '[{"kategorie": "wörtlich", "text": "\"Da hat''s ordentlich bumm gemacht!\"  2. \"Da hat''s einen Pumperer gemacht!\"  3. Da hat es mächtig gekracht!  4. Da hat’s ordentlich gescheppert!"}]'::jsonb, ''),
  ('an-poscha-haum', 'an Poscha haum', '', '', '', 'Wiener Sprüche, die sitzen!', 'einen Pascher haben', '[{"kategorie": "wörtlich", "text": "\"einen Dachschaden haben\""}, {"kategorie": "", "text": "\"nicht ganz richtig im Kopf sein\""}, {"kategorie": "", "text": "einen [[Klescher]] haben, einen [[Klopfer]] haben, einen [[Titscher]] haben, [[einen]] Wurm in der Marille haben"}]'::jsonb, 'Host an Poscha?'),
  ('host-an-poscha', 'Host an Poscha?', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Hast du einen Pascher?', '[{"kategorie": "wörtlich", "text": "\"Hast du einen Knall?\"  2. \"Bist du gestört?\"  3. (Deutschland): \"Hast du einen an der Waffel?"}]'::jsonb, 'an Poscha haum'),
  ('an-ditscha-haum', 'an Ditscha haum', '', '', '', 'Wiener Sprüche, die sitzen!', 'einen Titscher haben', '[{"kategorie": "wörtlich", "text": "\"einen Dachschaden haben\""}, {"kategorie": "", "text": "\"nicht ganz richtig im Kopf sein\""}, {"kategorie": "", "text": "\"einen an der Waffel haben\", [[einen Sprung in der Schüssel haben]], einen [[Klescher]] haben, einen [[Klopfer]] haben, einen [[Pascher]] haben"}]'::jsonb, 'Dea hod an muadsdrumm Ditscha - genauso wia sei Vooda!'),
  ('dea-hod-an-muadsdrumm-ditscha-genauso-wia-sei-vooda', 'Dea hod an muadsdrumm Ditscha - genauso wia sei Vooda!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Der hat einen mordstrumm Titscher - genauso wie sein Vater!', '[{"kategorie": "wörtlich", "text": "\"Der hat einen Sprung in der Schüssel – genauso wie sein Vater!\"  2. Der hat voll einen an der Waffel – genauso wie sein alter Herr!  3. Der hat voll den Knall – genauso wie sein Erzeuger!"}]'::jsonb, ''),
  ('de-klopfa-san-in-aana-laungan-rei-gschdaundn-und-haum-im-takt-es-zaache-weakschdickl-beoaweid', 'De Klopfa san in aana laungan Rei gschdaundn und haum im Takt es zaache Weakschdickl beoaweid!', '', '', '', 'Wiener Wörter mit schillernder Geschichte', 'Die Klopfer standen in einer langer Reihe und bearbeiteten im Takt das zähe Werkstück!', '[{"kategorie": "wörtlich", "text": "\"Die Klopfer standen in langer Reihe und bearbeiteten mit rhythmischem Schlag das zähe Werkstück!\"  2. Wie ein Uhrwerk schlugen die Klopfer in einer endlosen Reihe auf das widerständige Werkstück ein!  3. Die Klopfer standen in einer langen Reihe und bearbeiteten das zähe Material mit gleichmäßigen Schlägen!"}]'::jsonb, ''),
  ('da-klopfa-aun-da-tia-is-so-massiv-mit-dem-kunntasd-a-leich-aufweckn', 'Da Klopfa aun da Tia is so massiv, mit dem kunntasd a Leich aufweckn!', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'Der Klopfer an der Tür ist so massiv, mit dem könntest du eine Leiche aufwecken!', '[{"kategorie": "wörtlich", "text": "\"Der Türklopfer ist so ein Trümmerteil, damit könntest du Tote aufwecken!\"  2. Wenn du mit dem massiven Klopfer an die Tür hämmerst, schüttelt’s das ganze Haus – Tote inklusive!  3. So ein Monster von einem Türklopfer – da richten sich selbst die Toten auf, um nachzusehen, wer da Einlass begehrt!"}]'::jsonb, ''),
  ('min-oidn-klopfa-aus-weidnhoiz-hod-ma-mei-muada-friara-in-hintan-vasoid', 'Min oidn Klopfa aus Weidnhoiz hod ma mei Muada friara in Hintan vasoid!', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'Mit dem alten Klopfer aus Weidenholz hat mir meine Mutter früher den Hintern versohlt!', '[{"kategorie": "wörtlich", "text": "\"Früher hat mir meine Mutter mit dem alten Teppichklopfer aus Weidenholz ordentlich den Hintern poliert!\"  2. \"Den Weidenklopfer hat Mama nicht nur für Teppiche benutzt – mein Arsch tut mir heute noch weh!\"  3. Wenn meine Mutter den Klopfer aus dem Schrank nahm, wusste mein Hintern schon, was los war!"}]'::jsonb, ''),
  ('in-klopfa-haum-d-leit-friara-fiara-vuazeichn-vom-tood-ghoidn-drum-haums-jo-aa-toodnuua-zu-eam-gsoogd', 'In Klopfa haum d''Leit friara fiara Vuazeichn vom Tood ghoidn - drum haums jo aa ''Toodnuua'' zu eam gsoogd!', '', '', '', 'Viecher und Tiernamen auf Wienerisch', 'Den Klopfer haben die Leute früher für ein Vorzeichen des Todes gehalten - darum haben sie ja auch ''Totenuhr'' zu ihm gesagt!', '[{"kategorie": "wörtlich", "text": "\"Früher glaubte man, das Klopfen des Klopfkäfers sei ein Vorzeichen für den Tod – daher der Name ''Totenuhr''!\"  2. Manch einer sah einst im leisen Klopfen der Klopfkäfer den Ruf aus dem Jenseits – deshalb nannte man sie auch ''Totenuhr''!\"  3. Das dumpfe Klopfen aus dem Gebälk galt einst als flüsternde Vorbotin des Todes - wenn’s im Holz tickte, hieß es früher: „Die Totenuhr geht!\""}]'::jsonb, ''),
  ('a-klopfa-zum-auschdessn-und-daunn-kopfiwa-eine-in-mulatschag', 'A Klopfa zum Auschdessn, und daunn kopfiwa eine in Mulatschag!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Ein Klopfer zum Anstoßen - und dann kopfüber rein in den Mulatschak!', '[{"kategorie": "wörtlich", "text": "\"Ein Alko-Shot zum Anstoßen - und dann kopfüber rein in die Sause!\"  2. Ein Klopfer zum Anstoßen – und ab geht die Fete!  3. Ein schneller Klopfer – und dann volle Kraft voraus ins Feiermassaker!"}]'::jsonb, ''),
  ('des-klopfal-aun-da-tia-is-so-massiv-mit-dem-kunntasd-a-leich-aufweckn', 'Des Klopfal aun da Tia is so massiv, mit dem kunntasd a Leich aufweckn!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Das Klopferl an der Tür ist so massiv, mit dem könntest du eine Leiche aufwecken!', '[{"kategorie": "wörtlich", "text": "\"Das Türklopferchen ist so ein Trümmerteil, damit könntest du Tote aufwecken!\"  2. Wenn du mit dem massiven Klopferchen an die Tür hämmerst, schüttelt’s das ganze Haus – Tote inklusive!  3. So ein Monster von einem Türklopferchen – da richten sich selbst die Toten auf, um nachzusehen, wer da Einlass begehrt!"}]'::jsonb, ''),
  ('de-hod-a-klopfal', 'De hod a Klopfal!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Die hat ein Klopferl', '[{"kategorie": "wörtlich", "text": "\"Die hat einen Vogel!\"  2. Die hat einen Dachschaden!  3. Die ist nicht ganz dicht!  4. Die hat einen Sprung in der Schüssel!"}]'::jsonb, ''),
  ('da-opa-hod-a-klaans-klopfal-ghobd-owa-ea-saufd-weida-wii-ee-und-jee', 'Da Opa hod a klaans Klopfal ghobd - owa ea saufd weida wii ee und jee!', '', '', '', 'Krank & kuriert auf Wienerisch', 'Der Opa hat ein kleines Klopferl gehabt - aber er sauft weiter wie eh und je!', '[{"kategorie": "wörtlich", "text": "\"Opa hatte einen leichten Schlaganfall - aber er trinkt weiter wie eh und je!\"  2. Opa hat’s kurz umgehauen, aber er hat''s Klopferl weggesteckt wie nichts und hebt wieder seine Stamperln wie eh und je!  3. Der Arzt hat dem Opa g’sagt, er soll nach dem leichten Schlaganfall nichts mehr trinken – also trinkt Opa  nur noch die Hälfte. Das aber zweimal!"}]'::jsonb, ''),
  ('es-klopfal-haum-d-leit-friara-fiara-vuazeichn-vom-tood-ghoidn-drum-haums-jo-aa-toodnuua-zu-eam-gsoogd', 'Es Klopfal haum d''Leit friara fiara Vuazeichn vom Tood ghoidn - drum haums jo aa ''Toodnuua'' zu eam gsoogd!', '', '', '', 'Wiener Wörter mit schillernder Geschichte', 'Das Klopferchen haben die Leute früher für ein Vorzeichen des Todes gehalten - darum haben sie ja auch ''Totenuhr'' zu ihm gesagt!', '[{"kategorie": "wörtlich", "text": "\"Früher glaubte man, das Klopfen des Klopfkäferchens sei ein Vorzeichen für den Tod – daher der Name ''Totenuhr''!\"  2. Manch einer sah einst im leisen Klopfen der Klopfkäfer den Ruf aus dem Jenseits – deshalb nannte man sie auch ''Totenuhr''!\"  3. Das dumpfe Klopfen aus dem Gebälk galt einst als flüsternde Vorbotin des Todes - wenn’s im Holz tickte, hieß es früher: „Die Totenuhr geht!\""}]'::jsonb, ''),
